/**
 * API token rows. Only the hash of the secret is ever stored, and it never
 * leaves this module: mapped `ApiToken` values carry no hash.
 */
import { and, desc, eq, gt, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { brandId, brandStamp, brandStampOrNull } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { ApiTokenRow } from "@/server/db";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

function toApiToken(row: ApiTokenRow): ApiToken {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    userId: brandId<UserId>(row.userId),
    name: row.name,
    scope: row.scope,
    prefix: row.prefix,
    expiresAt: brandStamp(row.expiresAt),
    lastUsedAt: brandStampOrNull(row.lastUsedAt),
    revokedAt: brandStampOrNull(row.revokedAt),
    createdAt: brandStamp(row.createdAt),
  };
}

export interface NewApiToken {
  orgId: OrgId;
  userId: UserId;
  name: string;
  scope: ApiTokenScope;
  prefix: string;
  tokenHash: string;
  expiresAt: IsoTimestamp;
  createdAt: IsoTimestamp;
}

/**
 * Inserts unless the user already holds `limit` usable tokens in the org.
 * Count and insert run in one synchronous step, so concurrent callers cannot
 * both slip under the limit. Returns `null` when the limit is reached.
 */
export async function insertApiTokenWithinLimit(
  input: NewApiToken,
  limit: number,
): Promise<ApiToken | null> {
  const db = getDb();
  const usable = db
    .select({ id: apiTokens.id })
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, input.orgId),
        eq(apiTokens.userId, input.userId),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, input.createdAt),
      ),
    )
    .all();
  if (usable.length >= limit) return null;

  const row = db
    .insert(apiTokens)
    .values({ id: newId(), ...input })
    .returning()
    .get();
  return toApiToken(row);
}

export async function listApiTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  return getDb()
    .select()
    .from(apiTokens)
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)),
    )
    .orderBy(desc(apiTokens.createdAt), desc(apiTokens.id))
    .all()
    .map(toApiToken);
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

export async function listUnrevokedApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  return getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .all()
    .map(toApiToken);
}

/** Sets `revokedAt` only if still unrevoked; `null` when nothing changed. */
export async function markApiTokenRevoked(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

export async function touchApiTokenLastUsed(
  tokenId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at })
    .where(eq(apiTokens.id, tokenId))
    .run();
}
